<template><section class="hub"><button class="back" @click="$router.push(route.query.from==='personal' ? '/personal' : '/home')">← 返回{{route.query.from==='personal'?'个人中心':'首页'}}</button><h1>健康服务</h1><p>查看健康记录、提交服务申请或管理商城订单。</p><div class="hub-tabs"><button v-for="t in tabs" :key="t.id" :class="{chosen:active===t.id}" @click="select(t.id)">{{t.name}}</button></div><div class="hub-panel" v-if="active==='care' || active==='group'"><h2>{{active==='care'?'上门护理':'团检预约'}}</h2><p>填写服务需求，工作人员可在工作台查看并回复。提交申请不代表服务已安排。</p><form @submit.prevent="submitRequest"><label>需求说明<textarea v-model.trim="requestText" required maxlength="1000" rows="4" placeholder="请填写服务地点、希望时间和一般需求；请勿填写身份证号等敏感信息"></textarea></label><button class="primary" :disabled="busy">提交申请</button></form><h3>我的申请</h3><div v-for="r in myRequests" :key="r.requestId" class="item"><strong>{{r.serviceType==='HOME_CARE'?'上门护理':'团检预约'}} · {{r.status==='PENDING'?'待处理':'已回复'}}</strong><p>{{r.content}}</p><p v-if="r.reply">工作人员回复：{{r.reply}}</p></div><p v-if="!myRequests.length">暂无申请</p></div><div class="hub-panel" v-if="active==='chronic'"><h2>慢病健康记录</h2><p>记录日常测量值，方便后续与医务人员沟通。</p><form @submit.prevent="saveRecord"><label>日期<input v-model="record.recordDate" type="date" :max="today" required></label><label>记录类型<select v-model="record.category"><option>血压</option><option>血糖</option><option>体重</option><option>其他</option></select></label><label>记录值与单位<input v-model.trim="record.value" required maxlength="80" placeholder="例如 120/80 mmHg"></label><label>备注<input v-model.trim="record.note" maxlength="500" placeholder="可选"></label><button class="primary" :disabled="busy">保存记录</button></form><h3>我的记录</h3><div v-for="r in records" :key="r.recordId" class="item"><strong>{{format(r.recordDate)}} · {{r.category}}：{{r.value}}</strong><p v-if="r.note">{{r.note}}</p><button class="link" @click="removeRecord(r)">删除记录</button></div><p v-if="!records.length">暂无记录</p></div><div class="hub-panel" v-if="active==='shop'"><h2>健康商城</h2><p>项目内电子资料，使用模拟支付，不会产生实际扣款。</p><div v-for="p in products" :key="p.productId" class="item"><strong>{{p.title}} · ¥ {{p.price}}</strong><p>{{p.description}}</p><button class="outline" :disabled="busy" @click="buy(p)">创建订单</button></div><h3>商城订单</h3><div v-for="o in shopOrders" :key="o.shopOrderId" class="item"><strong>{{o.title}} · ¥ {{o.amount}}</strong><p>{{o.state==='UNPAID'?'待支付':o.state==='PAID'?'已支付':'已取消'}}</p><template v-if="o.state==='UNPAID'"><button class="primary" :disabled="busy" @click="pay(o)">模拟支付</button> <button class="outline" :disabled="busy" @click="cancel(o)">取消订单</button></template><div v-if="o.digitalContent" class="digital-content"><template v-if="o.title==='健康记录表'"><p>这里展示您在慢病管理中保存的健康记录。</p><div v-for="r in records" :key="r.recordId" class="record-preview"><strong>{{format(r.recordDate)}} · {{r.category}}</strong><span>{{r.value}}</span><small v-if="r.note">{{r.note}}</small></div><p v-if="!records.length">您还没有保存健康记录，可以先添加一条。</p><button class="outline" type="button" @click="select('chronic')">{{records.length?'管理健康记录':'添加健康记录'}}</button></template><template v-else><p>体检前可以按以下清单准备：</p><pre>{{o.digitalContent}}</pre></template></div></div><p v-if="!shopOrders.length">暂无商城订单</p></div><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p></section></template>
<script setup>
import {ref,reactive,onMounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import axios from 'axios'
const route=useRoute(),router=useRouter(),tabs=[{id:'chronic',name:'慢病管理'},{id:'care',name:'上门护理'},{id:'group',name:'团检预约'},{id:'shop',name:'商城与订单'}],active=ref(tabs.some(t=>t.id===route.query.tab)?route.query.tab:'chronic'),today=new Date().toLocaleDateString('en-CA'),record=reactive({recordDate:today,category:'血压',value:'',note:''}),requestText=ref(''),myRequests=ref([]),records=ref([]),products=ref([]),shopOrders=ref([]),busy=ref(false),error=ref(''),notice=ref('')
const api=axios.create({baseURL:'/tijian',timeout:10000});const format=s=>String(s||'').slice(0,10)
async function call(path,data={}){try{return (await api.post('/healthServices/'+path,data)).data}catch(e){if(e.response?.status===401){sessionStorage.removeItem('tijianUser');router.replace('/login')}throw e}}
async function refresh(){if(active.value==='care'||active.value==='group')myRequests.value=(await call('requests')).filter(r=>r.serviceType===(active.value==='care'?'HOME_CARE':'GROUP_EXAM'));if(active.value==='chronic')records.value=await call('records');if(active.value==='shop')[products.value,shopOrders.value,records.value]=await Promise.all([call('products'),call('shopOrders'),call('records')])}
async function select(id){active.value=id;requestText.value='';error.value='';notice.value='';try{await refresh()}catch(e){error.value='加载失败，请检查服务。'}}
async function run(action,message){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await action();await refresh();notice.value=message}catch(e){error.value='操作未完成，请检查输入和服务。'}finally{busy.value=false}}
function submitRequest(){run(async()=>{await call('request',{serviceType:active.value==='care'?'HOME_CARE':'GROUP_EXAM',content:requestText.value});requestText.value=''},'申请已提交，可在此查看回复。')}
function saveRecord(){run(async()=>{await call('record',record);record.value='';record.note=''},'记录已保存。')}
function removeRecord(r){if(window.confirm('确定删除这条记录？'))run(()=>call('deleteRecord',{recordId:r.recordId}),'记录已删除。')}
function buy(p){run(()=>call('buy',{productId:p.productId}),'订单已创建，请在下方支付。')}
function pay(o){if(window.confirm('确认模拟支付 ¥ '+o.amount+'？不会实际扣款。'))run(()=>call('payShop',{shopOrderId:o.shopOrderId}),'模拟支付成功，可查看资料。')}
function cancel(o){if(window.confirm('确定取消订单？'))run(()=>call('cancelShop',{shopOrderId:o.shopOrderId}),'订单已取消。')}
onMounted(()=>select(active.value))
</script>
<style scoped>.hub>p,.hub-panel>p{margin:14px 0;color:#718d84;line-height:1.7}.hub-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:22px 0}.hub-tabs button{padding:10px;border:1px solid #dcebe5;border-radius:8px;background:white;color:#41655a}.hub-tabs .chosen{background:#dff3e9;color:#137b64}.hub-panel{max-width:800px;background:white;border:1px solid #e3eeeb;border-radius:14px;padding:24px}.hub-panel form{display:grid;gap:14px;margin:20px 0}.hub-panel label{display:grid;gap:8px}.hub-panel input,.hub-panel select,.hub-panel textarea{padding:10px;border:1px solid #dcebe5;border-radius:8px;font:inherit}.hub-panel form button{justify-self:start}.hub-panel h3{margin-top:28px}.item{padding:17px 0;border-bottom:1px solid #edf3f0;white-space:pre-wrap;overflow-wrap:anywhere}.item p{margin:10px 0;color:#718d84}.item pre{white-space:pre-wrap;background:#f5faf7;padding:15px}.link{border:0;background:none;color:#138c75}.error{color:#b14b42}.notice{color:#138c75}.record-preview{display:grid;grid-template-columns:1fr auto;gap:5px;background:#f5faf7;padding:12px;margin:8px 0;font-size:13px}.record-preview small{grid-column:1 / -1;color:#718d84}.digital-content>p{line-height:1.6}
</style>